    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        # We'll use a dictionary to store the maximum sum ending at each key (nums[i] - i)
        maxleft = {}
        i = 0

        while i < n:
            key = nums[i] - i

            if key in maxleft:
                # Extend existing subsequence or start new one
                maxleft[key] = max(maxleft[key], maxleft[key] + nums[i], nums[i])
            else:
                # Initialize new key
                maxleft[key] = nums[i]

            # Find predecessor and successor positions using sorted keys
            keys = sorted(maxleft.keys())
            previdx = bisect.bisect_left(keys, key)
            nextidx = bisect.bisect_right(keys, key)

            # Handle predecessor case
            if previdx > 0:
                prev_key, prev_val = keys[previdx - 1], maxleft[keys[previdx - 1]]
                maxleft[key] = max(maxleft[key], prev_val + nums[i])

            # Handle successor case: remove entries that are dominated by current entry
            if nextidx < len(keys):
                next_key, next_val = keys[nextidx], maxleft[keys[nextidx]]
                if next_val <= maxleft[key]:
                    del maxleft[next_key]

            i += 1

        return max(maxleft.values()) if maxleft else nums[0]

